  .option-card.correct{border-color:#22c55e;background:#f0fdf4;}
  .option-card.wrong{border-color:#ef4444;background:#fef2f2;}
  .opt-head{display:flex;gap:9px;align-items:flex-start;}
  .opt-letter{
