  .option-card.wrong .opt-letter{background:#ef4444;color:#fff;}
  .opt-text{font-size:12.8px;line-height:1.55;color:#1e293b;font-weight:500;}
  .opt-feedback{
    display:none;margin-top:8px;padding-top:8px;border-top:1px dashed #cbd5e1;
    font-size:12.3px;line-height:1.6;color:#475569;
  }
  .option-card.correct .opt-feedback,
  .option-card.wrong .opt-feedback{display:block;}

  .axis-tick{font-size:11.5px;fill:#64748b;}
  .axis-label{font-size:12.5px;fill:#475569;font-weight:500;}
  .beaker-title{font-size:14px;font-weight:700;fill:#334155;}
  .beaker-status{font-size:11.5px;fill:#64748b;}
  .mini-label{font-size:10.5px;fill:#94a3b8;font-weight:700;}
</style>
</head>
<body>

<header>
  <h1>导电能力为什么先降后升？</h1>
  <p class="subtitle">拖动滑块或播放滴加，观察曲线、烧杯里的离子与沉淀怎样同步变化。</p>
</header>

<main>

  <!-- ================= 题目 ================= -->
  <section class="card prompt">
    <div class="mark">?</div>
    <div class="prompt-body">
      <p>某同学向一定体积的 Ba(OH)₂ 溶液中滴加稀硫酸，测得混合溶液的导电能力随时间变化如图。下列说法正确的是（　　）</p>
      <div class="opt-list">
        <span>A. AB 段溶液的导电能力减弱，说明生成的 BaSO₄ 不是电解质</span>
        <span>B. 实验时用 NaOH 溶液代替 Ba(OH)₂ 溶液也得到该曲线</span>
        <span>C. 实验时用稀 KHSO₄ 溶液代替稀硫酸也能得到该曲线</span>
        <span>D. 实验时用稀 MgSO₄ 溶液代替稀硫酸也能得到该曲线</span>
      </div>
    </div>
    <div class="thumb-wrap">
      <svg id="thumb" viewBox="0 0 300 170" role="img" aria-label="题图曲线"></svg>
      <span class="thumb-cap">题图（原实验实测曲线）</span>
    </div>
  </section>

  <!-- ================= 主区：曲线 + 烧杯 ================= -->
  <div class="grid-2">

    <section class="card">
      <div class="card-head">
        <h2>模型曲线</h2>
        <span class="tag" id="chartTag">原实验</span>
      </div>
      <svg id="chart" viewBox="0 0 620 390" role="img" aria-label="自由离子数随滴加量变化"></svg>
      <div class="controls">
        <button id="playBtn">播放滴加</button>
        <input id="tSlider" type="range" min="0" max="8" step="1" value="0" aria-label="滴加份数">
        <span id="tLabel" class="num-chip">0 份</span>
        <span id="freeLabel" class="num-chip grey">自由离子：12</span>
      </div>

      <div class="model-note">
        <b>模型设定（数字从哪来）：</b>把初始 Ba(OH)₂ 记为 <span class="k">4 个单元</span>，
        即 Ba²⁺×4、OH⁻×8，共 <span class="k">12 个自由离子</span>。
        每滴 1 份试剂恰好提供 1 个 SO₄²⁻ 和 2 个 H⁺，按化学计量比反应，
        所以原实验滴到 <span class="k">4 份</span>时 Ba²⁺ 与 OH⁻ 刚好同时用完，这就是最低点。<br>
        “份”只是比例示意，不是真实体积。可滴范围：原实验 / C / D 为 <b>0–8 份</b>，B（NaOH 起步只有 4 个 OH⁻）为 <b>0–4 份</b>，其最低点在 2 份。
      </div>

      <p class="footnote">
        <b>注意：</b>本图纵轴用“自由离子数”<b>近似</b>导电能力，只是<b>辅助定性示意</b>。
        真实导电能力还受离子种类（H⁺、OH⁻ 的导电本领明显更强）和体积稀释影响，
        所以题图的实测曲线是平滑的，起止高度、上升斜率都不会与本图一致。
        本图只用来判断<b>趋势</b>和<b>最低点是否为 0</b>。
      </p>
    </section>

    <section class="card">
      <div class="card-head">
        <h2>烧杯中的粒子</h2>
        <span class="tag" id="expTag">原实验</span>
      </div>
      <svg id="beaker" viewBox="0 0 420 390" role="img" aria-label="烧杯中的离子与沉淀示意"></svg>
      <div id="legend" class="legend"></div>
    </section>

  </div>

  <!-- ================= 探索 ================= -->
  <section class="card explore">
    <div class="card-head">
      <h2>换一种试剂，曲线还一样吗？</h2>
      <span class="tag">点击选题，再拖动滑块</span>
    </div>

    <div class="exp-tabs" id="expTabs"></div>

    <div class="step-row">
      <span class="step-label">分步观察：</span>
      <span id="stepRow" style="display:flex;gap:8px;flex-wrap:wrap;"></span>
    </div>

    <div id="expInfo" class="exp-info"></div>
  </section>

  <!-- ================= 选项 ================= -->
  <section class="card options">
    <h2>判断下列说法</h2>
    <p class="options-sub">点击任一卡片，页面会切换到对应试剂与状态，再结合曲线最低点作出判断。</p>
    <div class="option-grid" id="optionGrid"></div>
  </section>

</main>

<script>
/* =========================================================
   数据模型
   记号：把初始 Ba(OH)₂ 记作 4 个单元（Ba²⁺×4, OH⁻×8）
   每 1 份试剂 = 1 个 SO₄²⁻ + 2 个 H⁺（稀硫酸）或等价计量
   ========================================================= */
const experiments = {
  original: { id:'original', tab:'原实验 Ba(OH)₂+H₂SO₄', short:'原实验',
              color:'#2563eb', eqT:4, maxT:8, name:'Ba(OH)₂ + 稀 H₂SO₄' },
  B: { id:'B', tab:'B：NaOH', short:'B：NaOH',
       color:'#ea580c', eqT:2, maxT:4, name:'NaOH + 稀 H₂SO₄' },
  C: { id:'C', tab:'C：KHSO₄', short:'C：KHSO₄',
       color:'#9333ea', eqT:4, maxT:8, name:'Ba(OH)₂ + 稀 KHSO₄' },
  D: { id:'D', tab:'D：MgSO₄', short:'D：MgSO₄',
       color:'#0d9488', eqT:4, maxT:8, name:'Ba(OH)₂ + 稀 MgSO₄' }
};

const state = { exp:'original', t:0, playing:false, timer:null };

function clamp(v,a,b){ return Math.max(a, Math.min(b, v)); }

/* 返回某实验、某滴加量下的离子与沉淀情况 */
function getState(expId, t){
  t = Math.max(0, t);
  const ions = { Ba:0, OH:0, H:0, SO4:0, Na:0, K:0, Mg:0 };
  const prec = { BaSO4:0, MgOH2:0 };

  if (expId === 'original'){
    // Ba(OH)₂ + H₂SO₄ → BaSO₄↓ + 2H₂O
    const r = Math.min(t, 4);          // 已反应的份数
    ions.Ba   = 4 - r;
    ions.OH   = 8 - 2*r;
    prec.BaSO4 = r;
    if (t > 4){                        // 硫酸过量
      ions.SO4 = t - 4;
      ions.H   = 2*(t - 4);
    }
  }
  else if (expId === 'B'){
    // 4 个 NaOH 单元：Na⁺4、OH⁻4；H₂SO₄ 的量记为 0–4 份
    ions.Na = 4;
    ions.OH = Math.max(0, 4 - 2*t);    // 2H⁺ + 2OH⁻ → 2H₂O
    ions.SO4 = Math.min(t, 4);         // 硫酸根不被消耗
    ions.H  = Math.max(0, 2*(t - 2));
  }
  else if (expId === 'C'){
    // Ba(OH)₂ + KHSO₄ → BaSO₄↓ + KOH + H₂O，再 KOH + KHSO₄ → K₂SO₄ + H₂O
    const r = Math.min(t, 4);
    ions.Ba = 4 - r;
    prec.BaSO4 = r;
    ions.K  = t;                       // 每份带入 1 个 K⁺，从不消耗
    ions.OH = Math.max(0, 8 - t);      // 每份带走 1 个 OH⁻
    ions.SO4 = Math.max(0, t - 4);     // 前 4 份的 SO₄²⁻ 全部沉淀
  }
  else if (expId === 'D'){
    // Ba²⁺ + SO₄²⁻ → BaSO₄↓ ，Mg²⁺ + 2OH⁻ → Mg(OH)₂↓
    const r = Math.min(t, 4);
    ions.Ba = 4 - r;
    ions.OH = 8 - 2*r;
    prec.BaSO4 = r;
    prec.MgOH2 = r;
    if (t > 4){
      ions.Mg  = t - 4;
      ions.SO4 = t - 4;
    }
  }

  for (const k in ions) ions[k] = Math.max(0, ions[k]);
  for (const k in prec) prec[k] = Math.max(0, prec[k]);

  const freeCount = Object.keys(ions).reduce((a,k)=>a + ions[k], 0);
  return { ions, prec, freeCount };
}

/* 找曲线最低点 */
function findMin(id){
  const maxT = experiments[id].maxT;
  let bt = 0, bv = Infinity;
  for (let t = 0; t <= maxT + 1e-6; t += 0.05){
    const v = getState(id, t).freeCount;
    if (v < bv - 1e-9){ bv = v; bt = t; }
  }
  return { t: Math.round(bt*10)/10, v: Math.round(bv*100)/100 };
}

/* =========================================================
   文字宽度估计（用于白底标签）
   ========================================================= */
function textW(s, fs){
  let w = 0;
  for (const ch of s){
    w += /[\u4e00-\u9fa5\uff00-\uffef]/.test(ch) ? fs : fs*0.6;
  }
  return w;
}
function labelBox(x, y, text, color, fs, anchor){
  fs = fs || 11.5;
  const w = textW(text, fs) + 12;
  const h = fs + 8;
  let bx = x - w/2;
  if (anchor === 'start') bx = x - 6;
  if (anchor === 'end') bx = x - w + 6;
  return `<rect x="${bx.toFixed(1)}" y="${(y-h/2).toFixed(1)}" width="${w.toFixed(1)}" height="${h}" rx="5"
            fill="#ffffff" stroke="${color}" stroke-width="1.1" opacity="0.97"/>` +
         `<text x="${x}" y="${y}" text-anchor="${anchor||'middle'}" dominant-baseline="central"
            font-size="${fs}" font-weight="700" fill="${color}">${text}</text>`;
}

