/* =========================================================
   主曲线（模型示意）
   ========================================================= */
function drawChart(){
  const svg = document.getElementById('chart');
  const exp = experiments[state.exp];
  const W = 620, H = 390;
  const ml = 64, mr = 28, mt = 50, mb = 60;
  const plotW = W - ml - mr, plotH = H - mt - mb;
  const maxT = exp.maxT, maxY = 14;

  const sx = t => ml + (t / maxT) * plotW;
  const sy = v => mt + plotH * (1 - v / maxY);

  let s = `<rect width="${W}" height="${H}" fill="#ffffff"/>`;

  /* 网格 */
  for (let yv = 0; yv <= maxY; yv += 2){
    const y = sy(yv);
    s += `<line x1="${ml}" y1="${y}" x2="${ml+plotW}" y2="${y}" stroke="#eef2f7" stroke-width="1"/>`;
    s += `<text x="${ml-10}" y="${y+4}" text-anchor="end" class="axis-tick">${yv}</text>`;
  }
  for (let xt = 0; xt <= maxT + 1e-6; xt += 1){
    const x = sx(xt);
    s += `<line x1="${x}" y1="${mt}" x2="${x}" y2="${mt+plotH}" stroke="#f3f6fa" stroke-width="1"/>`;
    s += `<text x="${x}" y="${mt+plotH+20}" text-anchor="middle" class="axis-tick">${xt}</text>`;
  }

  /* 坐标轴 */
  s += `<line x1="${ml}" y1="${mt+plotH}" x2="${ml+plotW}" y2="${mt+plotH}" stroke="#475569" stroke-width="2"/>`;
  s += `<line x1="${ml}" y1="${mt}" x2="${ml}" y2="${mt+plotH}" stroke="#475569" stroke-width="2"/>`;

  /* “模型示意”角标 */
  s += `<rect x="${ml+8}" y="${mt+4}" width="118" height="21" rx="10.5" fill="#f1f5f9"/>`;
  s += `<text x="${ml+67}" y="${mt+18.5}" text-anchor="middle" font-size="11" font-weight="700" fill="#94a3b8">模型 · 定性示意</text>`;

  /* 完整曲线（淡色） */
  const N = 240;
  let full = '';
  for (let i = 0; i <= N; i++){
    const t = maxT * i / N;
    const v = getState(exp.id, t).freeCount;
    full += (i === 0 ? 'M' : 'L') + sx(t).toFixed(1) + ' ' + sy(v).toFixed(1);
  }
  s += `<path d="${full}" fill="none" stroke="${exp.color}" stroke-width="1.6" opacity="0.16"
          stroke-linejoin="round" stroke-linecap="round"/>`;

  /* 已滴加部分（加粗） */
  const endT = clamp(state.t, 0, maxT);
  let done = '';
  const M = 200;
  for (let i = 0; i <= M; i++){
    const t = endT * i / M;
    const v = getState(exp.id, t).freeCount;
    done += (i === 0 ? 'M' : 'L') + sx(t).toFixed(1) + ' ' + sy(v).toFixed(1);
  }
  s += `<path d="${done}" fill="none" stroke="${exp.color}" stroke-width="3.6"
          stroke-linecap="round" stroke-linejoin="round"/>`;

  /* 最低点标记 */
  const mn = findMin(exp.id);
  const mnx = sx(mn.t), mny = sy(mn.v);
  s += `<circle cx="${mnx}" cy="${mny}" r="5.5" fill="none" stroke="${exp.color}" stroke-width="2" stroke-dasharray="3 3"/>`;

  /* 当前点 */
  const stCur = getState(exp.id, state.t);
  const px = sx(state.t), py = sy(stCur.freeCount);
  s += `<line x1="${px}" y1="${py}" x2="${px}" y2="${mt+plotH}" stroke="${exp.color}"
          stroke-width="1.2" stroke-dasharray="4 4" opacity="0.5"/>`;
  s += `<circle cx="${px}" cy="${py}" r="7" fill="#ffffff" stroke="${exp.color}" stroke-width="3"/>`;

  const atMin = Math.abs(state.t - mn.t) < 0.01;

  /* 最低点标签：默认放在点的正上方；若与当前点标签冲突则下沉到左侧 */
  let mvx = mnx, mvy = mny - 30, mAnchor = 'middle';
  if (mny < mt + 34) mvy = mny + 26;                 // 若最低点很高（不可能但保险）
  if (mnx > ml + plotW - 90){ mvx = mnx - 14; mAnchor = 'end'; }
  if (mnx < ml + 60){ mvx = mnx + 14; mAnchor = 'start'; }
  s += labelBox(mvx, mvy, `最低点 ${Math.round(mn.v)}`, exp.color, 11, mAnchor);

  /* 当前值标签 */
  if (!atMin){
    let vx = px, vy = py - 22, va = 'middle';
    if (px > ml + plotW - 70){ vx = px - 16; va = 'end'; }
    else if (px < ml + 44){ vx = px + 18; va = 'start'; }
    if (Math.abs(vy - mvy) < 18 && Math.abs(vx - mvx) < 90){
      vy = py + 26;                                     // 与最低点标签错开
    }
    s += labelBox(vx, vy, String(Math.round(stCur.freeCount)), '#0f172a', 12, va);
  }

  /* 轴标题 */
  s += `<text x="${ml + plotW/2}" y="${H-16}" text-anchor="middle" class="axis-label">滴加试剂（份）</text>`;
  s += `<text x="18" y="${mt + plotH/2}" transform="rotate(-90 18 ${mt + plotH/2})"
          text-anchor="middle" class="axis-label">自由离子数（模型示意）</text>`;

  svg.innerHTML = s;
}

/* =========================================================
   烧杯
   ========================================================= */
function drawBeaker(){
  const svg = document.getElementById('beaker');
  const exp = experiments[state.exp];
  const st = getState(exp.id, state.t);

  /* 关键：统一使用 getState 返回的 prec 字段 */
  const ions = {};
  for (const k in st.ions) ions[k] = Math.round(st.ions[k]);
  const prec = {};
  for (const k in st.prec) prec[k] = Math.round(st.prec[k]);

  const W = 420, H = 390;
  let s = `<rect width="${W}" height="${H}" fill="#ffffff"/>`;

  /* 烧杯轮廓与液面 */
  s += `<path d="M70 60 L70 322 Q70 338 86 338 L334 338 Q350 338 350 322 L350 60"
          fill="none" stroke="#94a3b8" stroke-width="4" stroke-linecap="round"/>`;
  s += `<rect x="74" y="112" width="272" height="222" fill="#e8f4fd" opacity="0.9"/>`;
  s += `<line x1="74" y1="112" x2="346" y2="112" stroke="#38bdf8" stroke-width="2"/>`;
  s += `<line x1="94" y1="130" x2="94" y2="300" stroke="#ffffff" stroke-width="2" opacity="0.6"/>`;

  /* 离子样式定义 */
  const catDefs = [
    { k:'Ba', l:'Ba²⁺', c:'#2563eb', f:'#dbeafe', r:13,   fs:8.2 },
    { k:'Na', l:'Na⁺',  c:'#ea580c', f:'#ffedd5', r:12.5, fs:9   },
    { k:'K',  l:'K⁺',   c:'#0891b2', f:'#cffafe', r:12,   fs:9.5 },
    { k:'Mg', l:'Mg²⁺', c:'#0d9488', f:'#ccfbf1', r:13,   fs:8.2 },
    { k:'H',  l:'H⁺',   c:'#dc2626', f:'#fee2e2', r:11,   fs:9.5 }
  ];
  const anDefs = [
    { k:'OH',  l:'OH⁻',   c:'#16a34a', f:'#dcfce7', r:12.5, fs:8.6 },
    { k:'SO4', l:'SO₄²⁻', c:'#9333ea', f:'#f3e8ff', r:15,   fs:7.2 }
  ];

  const cats = [], ans = [];
  catDefs.forEach(d => { for (let i = 0; i < (ions[d.k]||0); i++) cats.push(d); });
  anDefs.forEach(d => { for (let i = 0; i < (ions[d.k]||0); i++) ans.push(d); });

  const cols = 3, dx = 36, rowY = 156, dy = 33;
  const catX = 122, anX = 246;

  function ionCircle(x, y, d){
    return `<circle cx="${x}" cy="${y}" r="${d.r}" fill="${d.f}" stroke="${d.c}" stroke-width="2"/>` +
           `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="central"
              font-size="${d.fs}" font-weight="700" fill="${d.c}">${d.l}</text>`;
  }

  cats.forEach((d, i) => {
    const col = i % cols, row = Math.floor(i / cols);
    s += ionCircle(catX + col*dx, rowY + row*dy, d);
  });
  ans.forEach((d, i) => {
    const col = i % cols, row = Math.floor(i / cols);
    s += ionCircle(anX + col*dx, rowY + row*dy, d);
  });

  /* 沉淀绘制 */
  function precipRow(n, label, y, fill, stroke){
    if (n <= 0) return '';
    const spacing = Math.min(34, 260 / Math.max(n,1));
    const w = 30, h = 15;
    const totalW = n * spacing;
    const startX = 210 - totalW/2 + spacing/2;
    let str = '';
    for (let i = 0; i < n; i++){
      const x = startX + i*spacing;
      str += `<rect x="${(x-w/2).toFixed(1)}" y="${(y-h/2).toFixed(1)}" width="${w}" height="${h}" rx="3"
                fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`;
      str += `<text x="${x.toFixed(1)}" y="${y}" text-anchor="middle" dominant-baseline="central"
                font-size="6.8" font-weight="700" fill="${stroke}">${label}</text>`;
    }
    return str;
  }

  const baN = prec.BaSO4 || 0;
  const mgN = prec.MgOH2 || 0;
  if (baN > 0 && mgN > 0){
    s += precipRow(baN, 'BaSO₄', 288, '#f8fafc', '#64748b');
    s += precipRow(mgN, 'Mg(OH)₂', 314, '#f0fdfa', '#0d9488');
  } else if (baN > 0){
    s += precipRow(baN, 'BaSO₄', 300, '#f8fafc', '#64748b');
  } else if (mgN > 0){
    s += precipRow(mgN, 'Mg(OH)₂', 300, '#f0fdfa', '#0d9488');
  }

  /* 文字标注 */
  s += `<text x="210" y="30" text-anchor="middle" class="beaker-title">${exp.name}</text>`;
  s += `<text x="${catX+36}" y="120" text-anchor="middle" class="mini-label">阳离子</text>`;
  s += `<text x="${anX+36}" y="120" text-anchor="middle" class="mini-label">阴离子</text>`;
  s += `<text x="210" y="368" text-anchor="middle" class="beaker-status">${statusLine()}</text>`;

  svg.innerHTML = s;
  drawLegend(ions, prec);
}

function drawLegend(ions, prec){
  const legend = document.getElementById('legend');
  const defs = {
    Ba:  { label:'Ba²⁺',  color:'#2563eb' },
    Na:  { label:'Na⁺',   color:'#ea580c' },
    K:   { label:'K⁺',    color:'#0891b2' },
    Mg:  { label:'Mg²⁺',  color:'#0d9488' },
    H:   { label:'H⁺',    color:'#dc2626' },
    OH:  { label:'OH⁻',   color:'#16a34a' },
    SO4: { label:'SO₄²⁻', color:'#9333ea' }
  };
  const items = [];
  for (const k in defs){
    if (ions[k] > 0){
      items.push(`<span class="legend-item"><span class="dot" style="background:${defs[k].color}"></span>${defs[k].label}</span>`);
    }
  }
  if (prec.BaSO4 > 0){
    items.push(`<span class="legend-item"><span class="square" style="border-color:#64748b"></span>BaSO₄↓</span>`);
  }
  if (prec.MgOH2 > 0){
    items.push(`<span class="legend-item"><span class="square" style="border-color:#0d9488"></span>Mg(OH)₂↓</span>`);
  }
  legend.innerHTML = items.length
    ? items.join('')
    : '<span class="legend-empty">溶液中暂无自由离子</span>';
}

/* =========================================================
   状态文字与分步说明
   ========================================================= */
function statusLine(){
  const exp = experiments[state.exp];
  const t = state.t;
  const st = getState(exp.id, t);

  if (t < 0.01) return '起始：自由离子较多，导电能力较强';
  if (Math.abs(t - exp.eqT) < 0.01){
    if (st.freeCount < 0.01) return '最低点：自由离子几乎为 0，导电能力最弱';
    return '最低点：仍有 ' + Math.round(st.freeCount) + ' 个自由离子，导电能力不为 0';
  }
  if (t < exp.eqT) return '滴加中：自由离子减少，导电能力下降';
  return '试剂过量：自由离子重新增多，导电能力回升';
}

function stageInfo(){
  const id = state.exp, t = state.t, e = experiments[id];

  if (id === 'original'){
    if (t < 0.01) return {
      eq:'起始：Ba(OH)₂ = Ba²⁺ + 2OH⁻',
      note:'4 个 Ba²⁺ + 8 个 OH⁻ = 12 个自由离子，导电能力最强。'
    };
    if (t < e.eqT - 0.01) return {
      eq:'Ba(OH)₂ + H₂SO₄ → BaSO₄↓ + 2H₂O',
      note:'Ba²⁺ 被 SO₄²⁻ 沉淀、OH⁻ 被 H⁺ 中和；生成的 BaSO₄ 是沉淀、水是弱电解质，都不再提供自由离子。'
    };
    if (t < e.eqT + 0.01) return {
      eq:'恰好完全反应：Ba(OH)₂ + H₂SO₄ → BaSO₄↓ + 2H₂O',
      note:'溶液中几乎没有自由离子，导电能力降到最低（对应题图的 a 点）。'
    };
    return {
      eq:'H₂SO₄ 过量：H₂SO₄ = 2H⁺ + SO₄²⁻',
      note:'过量的硫酸带来新的自由离子，导电能力回升。'
    };
  }

  if (id === 'B'){
    if (t < 0.01) return {
      eq:'起始：NaOH = Na⁺ + OH⁻',
      note:'4 个 Na⁺ + 4 个 OH⁻ = 8 个自由离子。'
    };
    if (t < e.eqT - 0.01) return {
      eq:'2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O',
      note:'OH⁻ 被中和，但 Na⁺ 不参与反应，始终留在溶液中。'
    };
    if (t < e.eqT + 0.01) return {
      eq:'OH⁻ 恰好被中和：溶液中剩 Na⁺ 与 SO₄²⁻',
      note:'4 个 Na⁺ + 2 个 SO₄²⁻ = 6 个自由离子，最低点明显不为 0。'
    };
    return {
      eq:'H₂SO₄ 过量：H₂SO₄ = 2H⁺ + SO₄²⁻',
      note:'H⁺、SO₄²⁻ 继续增多，导电能力回升。'
    };
  }

  if (id === 'C'){
    if (t < 0.01) return {
      eq:'起始：Ba(OH)₂ = Ba²⁺ + 2OH⁻',
      note:'4 个 Ba²⁺ + 8 个 OH⁻ = 12 个自由离子。'
    };
    if (t < e.eqT - 0.01) return {
      eq:'第一步：Ba(OH)₂ + KHSO₄ → BaSO₄↓ + KOH + H₂O',
      note:'Ba²⁺ 被沉淀、进入溶液的 K⁺ 与消耗的 Ba²⁺ 等量，OH⁻ 只减少 1 个，所以每份净减少 1 个自由离子。'
    };
    if (t < e.eqT + 0.01) return {
      eq:'第一步完成：溶液是 KOH 和 BaSO₄ 沉淀',
      note:'4 个 K⁺ + 4 个 OH⁻ = 8 个自由离子，最低点离 0 还很远。'
    };
    if (t < e.maxT - 0.01) return {
      eq:'第二步：KOH + KHSO₄ → K₂SO₄ + H₂O',
      note:'OH⁻ 被中和，同时 K⁺、SO₄²⁻ 增多，自由离子数回升。'
    };
    return {
      eq:'总反应：Ba(OH)₂ + 2KHSO₄ → BaSO₄↓ + K₂SO₄ + 2H₂O',
      note:'此时溶液为 K₂SO₄，导电能力已从最低点回升。'
    };
  }

  if (id === 'D'){
    if (t < 0.01) return {
      eq:'起始：Ba(OH)₂ = Ba²⁺ + 2OH⁻',
      note:'4 个 Ba²⁺ + 8 个 OH⁻ = 12 个自由离子。'
    };
    if (t < e.eqT - 0.01) return {
      eq:'Ba²⁺ + SO₄²⁻ → BaSO₄↓ ； Mg²⁺ + 2OH⁻ → Mg(OH)₂↓',
      note:'两条“去掉自由离子”的路径同时进行，自由离子迅速减少。'
    };
    if (t < e.eqT + 0.01) return {
      eq:'恰好完全反应：Ba(OH)₂ + MgSO₄ → BaSO₄↓ + Mg(OH)₂↓',
      note:'自由离子几乎为 0，导电能力降到最低。'
    };
    return {
      eq:'MgSO₄ 过量：MgSO₄ = Mg²⁺ + SO₄²⁻',
      note:'Mg²⁺、SO₄²⁻ 重新增多，导电能力回升。'
    };
  }
  return { eq:'', note:'' };
}

/* =========================================================
   分步按钮
   ========================================================= */
function renderSteps(){
  const e = experiments[state.exp];
  const row = document.getElementById('stepRow');
  let defs;
  if (state.exp === 'original'){
    defs = [{t:0,l:'起点'},{t:2,l:'AB 段'},{t:4,l:'B 点（最低）'},{t:7,l:'BC 段'}];
  } else {
    defs = [{t:0,l:'起点'},{t:e.eqT/2,l:'下降中'},{t:e.eqT,l:'最低点'},{t:e.maxT,l:'过量后'}];
  }
  row.innerHTML = '';
  defs.forEach(d => {
    const b = document.createElement('button');
    b.className = 'step-btn' + (Math.abs(state.t - d.t) < 0.01 ? ' active' : '');
    b.textContent = d.l;
    b.addEventListener('click', () => {
      state.t = d.t;
      stopPlay();
      updateAll();
    });
    row.appendChild(b);
  });
}

/* =========================================================
   统一更新
   ========================================================= */
function updateAll(){
  const e = experiments[state.exp];
  state.t = clamp(state.t, 0, e.maxT);

  const slider = document.getElementById('tSlider');
  slider.max = e.maxT;
  slider.step = 1;
  slider.value = state.t;

  const st = getState(state.exp, state.t);
  document.getElementById('tLabel').textContent = state.t + ' 份 / 共 ' + e.maxT + ' 份';
  document.getElementById('freeLabel').textContent = '自由离子：' + Math.round(st.freeCount);
  document.getElementById('expTag').textContent = e.short;
  document.getElementById('chartTag').textContent = e.short;

  document.querySelectorAll('.exp-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.exp === state.exp);
  });

  const info = stageInfo();
  const mn = findMin(state.exp);
  const minWarn = mn.v < 0.01
    ? '（导电能力接近 0）'
    : '（<span class="warn">不为 0</span>，导电能力不会降到接近 0）';

  document.getElementById('expInfo').innerHTML =
    `<div class="eqline">${info.eq}</div>` +
    `<div class="noteline">${info.note}</div>` +
    `<div class="minline">曲线最低点：滴加 <b>${mn.t}</b> 份时，自由离子数 = <b>${Math.round(mn.v)}</b> ${minWarn}</div>`;

  drawChart();
  drawBeaker();
  renderSteps();
}

/* =========================================================
   播放
   ========================================================= */
function stopPlay(){
  if (state.timer) clearInterval(state.timer);
  state.timer = null;
  state.playing = false;
  const btn = document.getElementById('playBtn');
  if (btn) btn.textContent = '播放滴加';
}

function startPlay(){
  stopPlay();
  state.t = 0;
  state.playing = true;
  const btn = document.getElementById('playBtn');
  btn.textContent = '暂停';
  updateAll();

  state.timer = setInterval(() => {
    const maxT = experiments[state.exp].maxT;
    if (state.t >= maxT){ stopPlay(); return; }
    state.t = Math.min(maxT, state.t + 1);
    updateAll();
  }, 540);
}

/* =========================================================
   选项
   ========================================================= */
const optionData = {
  A: {
    correct:false, exp:'original', t:2,
    feedback:'× 导电能力的决定因素是溶液中自由离子的浓度，不是“是不是电解质”。BaSO₄ 虽然难溶，但溶解的那一点点完全电离，它仍是强电解质。AB 段减弱是因为 Ba²⁺、OH⁻ 被不断消耗变成沉淀和水。'
  },
  B: {
    correct:false, exp:'B', t:2,
    feedback:'× 换成 NaOH 后，Na⁺ 全程留在溶液中。到最低点时溶液里仍有 4 个 Na⁺ 和 2 个 SO₄²⁻，共 6 个自由离子，曲线最低处明显高于 0，与题图不符。'
  },
  C: {
    correct:false, exp:'C', t:4,
    feedback:'× 换成 KHSO₄ 后，K⁺ 也全程留在溶液中。Ba²⁺ 刚被沉淀完时，溶液是 KOH，含 4 个 K⁺ + 4 个 OH⁻ = 8 个自由离子，最低点同样不为 0。'
  },
  D: {
    correct:true, exp:'D', t:4,
    feedback:'√ MgSO₄ 中的 SO₄²⁻ 沉淀 Ba²⁺，Mg²⁺ 又与 OH⁻ 生成 Mg(OH)₂ 沉淀——两条“去掉自由离子”的路径同时进行，4 份时自由离子几乎为 0；再滴加又带入 Mg²⁺、SO₄²⁻，导电能力回升。趋势和最低点位置都与题图一致。'
  }
};

function initOptions(){
  const grid = document.getElementById('optionGrid');
  const texts = {
    A:'AB 段溶液的导电能力减弱，说明生成的 BaSO₄ 不是电解质',
    B:'实验时用 NaOH 溶液代替 Ba(OH)₂ 溶液也得到该曲线',
    C:'实验时用稀 KHSO₄ 溶液代替稀硫酸也能得到该曲线',
    D:'实验时用稀 MgSO₄ 溶液代替稀硫酸也能得到该曲线'
  };
  Object.keys(texts).forEach(key => {
    const btn = document.createElement('button');
    btn.className = 'option-card';
    btn.dataset.opt = key;
    btn.innerHTML =
      `<div class="opt-head">` +
        `<span class="opt-letter">${key}</span>` +
        `<span class="opt-text">${texts[key]}</span>` +
      `</div>` +
      `<div class="opt-feedback"></div>`;

    btn.addEventListener('click', () => {
      const data = optionData[key];
      stopPlay();
      state.exp = data.exp;
      state.t = data.t;
      document.querySelectorAll('.option-card').forEach(c => {
        c.classList.remove('correct','wrong');
        c.querySelector('.opt-feedback').textContent = '';
      });
      btn.classList.add(data.correct ? 'correct' : 'wrong');
      btn.querySelector('.opt-feedback').textContent = data.feedback;
      updateAll();
    });
    grid.appendChild(btn);
  });
}

/* =========================================================
   实验标签
   ========================================================= */
function initTabs(){
  const box = document.getElementById('expTabs');
  Object.values(experiments).forEach(e => {
    const b = document.createElement('button');
    b.className = 'exp-tab';
    b.dataset.exp = e.id;
    b.innerHTML = `<span class="tab-dot" style="background:${e.color}"></span>${e.tab}`;
    b.addEventListener('click', () => {
      stopPlay();
      state.exp = e.id;
      state.t = Math.min(state.t, e.maxT);
      document.querySelectorAll('.option-card').forEach(c => {
        c.classList.remove('correct','wrong');
        c.querySelector('.opt-feedback').textContent = '';
      });
      updateAll();
    });
    box.appendChild(b);
  });
}

/* =========================================================
   控件
   ========================================================= */
function initControls(){
  document.getElementById('tSlider').addEventListener('input', ev => {
    state.t = Number(ev.target.value);
    stopPlay();
    updateAll();
  });
  document.getElementById('playBtn').addEventListener('click', () => {
    if (state.playing) stopPlay();
    else startPlay();
  });
}

/* =========================================================
   启动
   ========================================================= */
drawThumb();
initTabs();
initOptions();
initControls();
state.t = 0;
updateAll();
</script>
